ALTER TABLE public.hr_branches ADD COLUMN company_id uuid REFERENCES public.companies(id), ADD COLUMN manager_id uuid REFERENCES public.hr_employees(id), ADD COLUMN code text NOT NULL DEFAULT '', ADD COLUMN address text NOT NULL DEFAULT '', ADD COLUMN state text NOT NULL DEFAULT '', ADD COLUMN postal_code text NOT NULL DEFAULT '', ADD COLUMN email text NOT NULL DEFAULT '', ADD COLUMN phone text NOT NULL DEFAULT '';
ALTER TABLE public.hr_designations ADD COLUMN company_id uuid REFERENCES public.companies(id), ADD COLUMN branch_id uuid REFERENCES public.hr_branches(id), ADD COLUMN description text NOT NULL DEFAULT '';
ALTER TABLE public.hr_departments ADD COLUMN company_id uuid REFERENCES public.companies(id), ADD COLUMN branch_id uuid REFERENCES public.hr_branches(id);
ALTER TABLE public.hr_employees ADD COLUMN company_id uuid REFERENCES public.companies(id);
CREATE OR REPLACE FUNCTION public.hrm_allowed(_module text,_action text,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') AND (public.has_role(auth.uid(),'super_admin') OR (_company IS NOT NULL AND public.is_company_member(auth.uid(),_company) AND NOT public.has_role(auth.uid(),'client') AND EXISTS(SELECT 1 FROM public.user_access_roles ur JOIN public.access_roles r ON r.id=ur.role_id WHERE ur.user_id=auth.uid() AND (_module||'.'||_action)=ANY(r.permissions)))) $$;
CREATE OR REPLACE FUNCTION public.hrm_owns_employee(_employee uuid,_company uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.hr_employees e JOIN public.profiles p ON p.id=e.profile_id WHERE e.id=_employee AND e.profile_id=auth.uid() AND e.is_active AND e.access_status='approved' AND p.account_status='active' AND e.company_id=_company AND public.is_company_member(auth.uid(),_company) AND NOT public.has_role(auth.uid(),'client')) $$;
CREATE OR REPLACE FUNCTION public.hrm_audience(_company uuid,_branch uuid,_department uuid,_audience jsonb) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'client') AND public.is_company_member(auth.uid(),_company) AND EXISTS(SELECT 1 FROM public.hr_employees e JOIN public.profiles p ON p.id=e.profile_id WHERE e.profile_id=auth.uid() AND e.company_id=_company AND e.is_active AND e.access_status='approved' AND p.account_status='active' AND (_branch IS NULL OR e.branch_id=_branch) AND (_department IS NULL OR e.department_id=_department) AND (coalesce(_audience->>'audience','all')='all' OR (coalesce(_audience->'employee_ids','[]') ? e.id::text) OR (coalesce(_audience->>'audience','')='roles' AND EXISTS(SELECT 1 FROM public.user_access_roles u WHERE u.user_id=auth.uid() AND coalesce(_audience->'role_ids','[]') ? u.role_id::text)))) $$;
GRANT EXECUTE ON FUNCTION public.hrm_allowed(text,text,uuid), public.hrm_owns_employee(uuid,uuid), public.hrm_audience(uuid,uuid,uuid,jsonb) TO authenticated;
