CREATE TABLE public.hr_leave_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),title text NOT NULL DEFAULT 'Leave request',kind text NOT NULL CHECK(kind IN('casual','sick','earned','unpaid','other')),start_date date NOT NULL,end_date date NOT NULL,half_day boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','correction','cancelled')),reason text NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 2000),approver_id uuid,decided_at timestamptz,details jsonb NOT NULL DEFAULT '{}',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(end_date>=start_date),CHECK(NOT half_day OR start_date=end_date));
