CREATE TABLE public.hr_payroll(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES public.companies(id),branch_id uuid REFERENCES public.hr_branches(id),employee_id uuid NOT NULL REFERENCES public.hr_employees(id),salary_period date NOT NULL,salary_date date NOT NULL,basic numeric(14,2) NOT NULL CHECK(basic>=0),allowances numeric(14,2) NOT NULL DEFAULT 0 CHECK(allowances>=0),bonuses numeric(14,2) NOT NULL DEFAULT 0 CHECK(bonuses>=0),deductions numeric(14,2) NOT NULL DEFAULT 0 CHECK(deductions>=0),gross numeric(14,2) GENERATED ALWAYS AS(basic+allowances+bonuses) STORED,net numeric(14,2) GENERATED ALWAYS AS(basic+allowances+bonuses-deductions) STORED,status text NOT NULL DEFAULT 'unpaid' CHECK(status IN('unpaid','paid')),payment_reference text NOT NULL DEFAULT '',paid_at timestamptz,notes text NOT NULL DEFAULT '',created_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,salary_period),CHECK(deductions<=basic+allowances+bonuses),CHECK(extract(day from salary_period)=1),CHECK(status<>'paid' OR(length(trim(payment_reference))>=3 AND paid_at IS NOT NULL)));
GRANT SELECT ON public.hr_payroll TO authenticated; GRANT ALL ON public.hr_payroll TO service_role;
ALTER TABLE public.hr_payroll ENABLE ROW LEVEL SECURITY;
