CREATE OR REPLACE FUNCTION public.hrm_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE module text; c uuid; b uuid; oldj jsonb; newj jsonb; e uuid; BEGIN module:=CASE TG_TABLE_NAME WHEN 'hr_holidays' THEN 'hr_holiday' WHEN 'hr_meetings' THEN 'hr_meeting' WHEN 'hr_schedules' THEN 'hr_calendar' WHEN 'hr_announcements' THEN 'hr_announcement' WHEN 'hr_documents' THEN 'hr_document' WHEN 'hr_branches' THEN 'hr_branch' WHEN 'hr_designations' THEN 'hr_designation' ELSE TG_TABLE_NAME END; IF TG_OP='DELETE' THEN oldj:=to_jsonb(OLD); c:=(oldj->>'company_id')::uuid; IF TG_TABLE_NAME='hr_announcements' AND OLD.status<>'draft' THEN RAISE EXCEPTION 'Archive published announcements instead'; END IF; ELSE newj:=to_jsonb(NEW); c:=(newj->>'company_id')::uuid; b:=(newj->>'branch_id')::uuid; IF TG_OP='UPDATE' THEN oldj:=to_jsonb(OLD); IF (oldj->>'company_id') IS DISTINCT FROM (newj->>'company_id') THEN RAISE EXCEPTION 'Company cannot be changed on an existing record'; END IF; END IF; IF b IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_branches WHERE id=b AND company_id=c) THEN RAISE EXCEPTION 'Branch must belong to the selected company'; END IF; IF newj->>'department_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_departments WHERE id=(newj->>'department_id')::uuid AND company_id=c) THEN RAISE EXCEPTION 'Department must belong to the selected company'; END IF; IF auth.uid() IS NOT NULL AND TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); END IF; IF TG_OP='UPDATE' AND TG_TABLE_NAME NOT IN('hr_branches','hr_designations') THEN NEW.updated_at:=now(); END IF; END IF; IF auth.uid() IS NOT NULL THEN INSERT INTO public.hr_audit_logs(entity_type,entity_id,company_id,action,before_data,after_data) VALUES(module,coalesce((newj->>'id')::uuid,(oldj->>'id')::uuid),c,lower(TG_OP),oldj,newj); END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
DO $$ DECLARE t text; m text; BEGIN FOREACH t IN ARRAY ARRAY['hr_holidays','hr_meetings','hr_schedules','hr_announcements','hr_documents'] LOOP m:=CASE t WHEN 'hr_holidays' THEN 'hr_holiday' WHEN 'hr_meetings' THEN 'hr_meeting' WHEN 'hr_schedules' THEN 'hr_calendar' WHEN 'hr_announcements' THEN 'hr_announcement' ELSE 'hr_document' END; EXECUTE format('CREATE POLICY %I ON public.%I FOR SELECT TO authenticated USING(public.hrm_allowed(%L,''view'',company_id))',t||'_admin_read',t,m); EXECUTE format('CREATE POLICY %I ON public.%I FOR INSERT TO authenticated WITH CHECK(public.hrm_allowed(%L,''create'',company_id) AND created_by=auth.uid())',t||'_insert',t,m); EXECUTE format('CREATE POLICY %I ON public.%I FOR UPDATE TO authenticated USING(public.hrm_allowed(%L,''edit'',company_id)) WITH CHECK(public.hrm_allowed(%L,''edit'',company_id))',t||'_update',t,m,m); IF t<>'hr_documents' THEN EXECUTE format('CREATE POLICY %I ON public.%I FOR DELETE TO authenticated USING(public.hrm_allowed(%L,''delete'',company_id))',t||'_delete',t,m); END IF; EXECUTE format('CREATE TRIGGER %I BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.hrm_record_guard()',t||'_guard',t); EXECUTE format('CREATE INDEX %I ON public.%I(company_id,created_at)',t||'_scope',t); END LOOP; END $$;
CREATE POLICY hr_holiday_employee_read ON public.hr_holidays FOR SELECT TO authenticated USING(status='active' AND public.hrm_audience(company_id,branch_id,NULL,'{}'));
CREATE POLICY hr_meeting_employee_read ON public.hr_meetings FOR SELECT TO authenticated USING(public.hrm_audience(company_id,branch_id,department_id,details));
CREATE POLICY hr_schedule_employee_read ON public.hr_schedules FOR SELECT TO authenticated USING(public.hrm_audience(company_id,branch_id,NULL,details));
CREATE POLICY hr_announcement_employee_read ON public.hr_announcements FOR SELECT TO authenticated USING(status='published' AND start_date<=(now() AT TIME ZONE 'Asia/Kolkata')::date AND (end_date IS NULL OR end_date>=(now() AT TIME ZONE 'Asia/Kolkata')::date) AND public.hrm_audience(company_id,branch_id,department_id,details));
CREATE POLICY hr_document_employee_read ON public.hr_documents FOR SELECT TO authenticated USING(status='active' AND (end_date IS NULL OR end_date>=(now() AT TIME ZONE 'Asia/Kolkata')::date) AND public.hrm_audience(company_id,branch_id,department_id,details));
CREATE POLICY hr_branch_scoped_read ON public.hr_branches FOR SELECT TO authenticated USING(public.hrm_allowed('hr_branch','view',company_id));
CREATE POLICY hr_branch_scoped_insert ON public.hr_branches FOR INSERT TO authenticated WITH CHECK(public.hrm_allowed('hr_branch','create',company_id));
CREATE POLICY hr_branch_scoped_edit ON public.hr_branches FOR UPDATE TO authenticated USING(public.hrm_allowed('hr_branch','edit',company_id)) WITH CHECK(public.hrm_allowed('hr_branch','edit',company_id));
CREATE POLICY hr_branch_scoped_delete ON public.hr_branches FOR DELETE TO authenticated USING(public.hrm_allowed('hr_branch','delete',company_id));
CREATE POLICY hr_designation_scoped_read ON public.hr_designations FOR SELECT TO authenticated USING(public.hrm_allowed('hr_designation','view',company_id));
CREATE POLICY hr_designation_scoped_insert ON public.hr_designations FOR INSERT TO authenticated WITH CHECK(public.hrm_allowed('hr_designation','create',company_id));
CREATE POLICY hr_designation_scoped_edit ON public.hr_designations FOR UPDATE TO authenticated USING(public.hrm_allowed('hr_designation','edit',company_id)) WITH CHECK(public.hrm_allowed('hr_designation','edit',company_id));
CREATE POLICY hr_designation_scoped_delete ON public.hr_designations FOR DELETE TO authenticated USING(public.hrm_allowed('hr_designation','delete',company_id));
CREATE OR REPLACE FUNCTION public.hrm_org_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='DELETE' THEN IF TG_TABLE_NAME='hr_branches' AND (EXISTS(SELECT 1 FROM public.hr_employees WHERE branch_id=OLD.id) OR EXISTS(SELECT 1 FROM public.hr_designations WHERE branch_id=OLD.id)) THEN RAISE EXCEPTION 'Branch is in use; deactivate it instead'; END IF; IF TG_TABLE_NAME='hr_designations' AND EXISTS(SELECT 1 FROM public.hr_employees WHERE designation_id=OLD.id) THEN RAISE EXCEPTION 'Designation is in use; deactivate it instead'; END IF; RETURN OLD; END IF; IF TG_OP='UPDATE' AND NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'Company cannot be changed on an existing record'; END IF; IF TG_TABLE_NAME='hr_branches' AND NEW.manager_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_employees WHERE id=NEW.manager_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Manager must belong to the selected company'; END IF; IF TG_TABLE_NAME='hr_designations' AND NEW.branch_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.hr_branches WHERE id=NEW.branch_id AND company_id=NEW.company_id) THEN RAISE EXCEPTION 'Branch must belong to the selected company'; END IF; RETURN NEW; END $$;
CREATE TRIGGER hr_branch_dependency BEFORE INSERT OR UPDATE OR DELETE ON public.hr_branches FOR EACH ROW EXECUTE FUNCTION public.hrm_org_guard();
CREATE TRIGGER hr_designation_dependency BEFORE INSERT OR UPDATE OR DELETE ON public.hr_designations FOR EACH ROW EXECUTE FUNCTION public.hrm_org_guard();
CREATE INDEX hr_employee_company ON public.hr_employees(company_id);
CREATE INDEX hr_attendance_scope_date ON public.hr_attendance(company_id,attendance_date);
CREATE INDEX hr_payroll_scope_period ON public.hr_payroll(company_id,salary_period);
CREATE POLICY hr_private_no_browser_access ON storage.objects FOR SELECT TO authenticated USING(bucket_id='hrm-private-files' AND false);